import java.io.*; import java.util.*; class Result { private static int[][] pref; private static long[] fact; private static long[] invFact; private static final int MOD = 1000000007; public static void initialize(String s) { int n = s.length(); pref = new int[26][n + 1]; for (int i = 0; i < n; i++) { for (int j = 0; j < 26; j++) pref[j][i + 1] = pref[j][i]; pref[s.charAt(i) - 'a'][i + 1]++; } fact = new long[n + 1]; invFact = new long[n + 1]; fact[0] = 1; for (int i = 1; i <= n; i++) fact[i] = (fact[i - 1] * i) % MOD; invFact[n] = power(fact[n], MOD - 2); for (int i = n - 1; i >= 0; i--) invFact[i] = (invFact[i + 1] * (i + 1)) % MOD; } public static int answerQuery(int l, int r) { int[] counts = new int[26]; int oddCount = 0; int halfSum = 0; for (int i = 0; i < 26; i++) { counts[i] = pref[i][r] - pref[i][l - 1]; if (counts[i] % 2 != 0) oddCount++; halfSum += counts[i] / 2; } long ans = fact[halfSum]; for (int i = 0; i < 26; i++) { if (counts[i] / 2 > 0) { ans = (ans * invFact[counts[i] / 2]) % MOD; } } if (oddCount > 0) { ans = (ans * oddCount) % MOD; } return (int) ans; } private static long power(long base, long exp) { long res = 1; base %= MOD; while (exp > 0) { if (exp % 2 == 1) res = (res * base) % MOD; base = (base * base) % MOD; exp /= 2; } return res; } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out)); String s = br.readLine(); Result.initialize(s); int q = Integer.parseInt(br.readLine().trim()); for (int i = 0; i < q; i++) { StringTokenizer st = new StringTokenizer(br.readLine()); int l = Integer.parseInt(st.nextToken()); int r = Integer.parseInt(st.nextToken()); bw.write(String.valueOf(Result.answerQuery(l, r))); bw.newLine(); } bw.close(); br.close(); } }